package cl.duoc.tienda.notificacion.service;
import cl.duoc.tienda.notificacion.dto.*; import cl.duoc.tienda.notificacion.model.*; import cl.duoc.tienda.notificacion.repository.*; import java.util.*; import org.slf4j.*; import org.springframework.stereotype.Service;
@Service public class NotificacionService { private static final Logger log=LoggerFactory.getLogger(NotificacionService.class); private final NotificacionRepository repo; public NotificacionService(NotificacionRepository r){repo=r;} public List<Notificacion> listar(){return repo.findAll();} public Notificacion buscar(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Notificacion no encontrado: "+id));} public Notificacion guardar(NotificacionRequest d){ Notificacion e=new Notificacion(d.usuarioId(), d.mensaje(), d.leida()); log.info("Guardando notificacion"); return repo.save(e);} public Notificacion actualizar(Long id,NotificacionRequest d){buscar(id); Notificacion e=new Notificacion(d.usuarioId(), d.mensaje(), d.leida()); e.setId(id); return repo.save(e);} public void eliminar(Long id){buscar(id);repo.deleteById(id);log.info("Notificacion eliminado: {}",id);} }
